import{z as n,x as s,o as t,c as d,q as A,j as l,D as B,d as e,s as r,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"风险选择与 Rothschild–Stiglitz 的深化","description":"","frontmatter":{"title":"风险选择与 Rothschild–Stiglitz 的深化","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hi-risk-selection.md","filePath":"econ/hi-risk-selection.md","lastUpdated":1791063341000}'),h={name:"econ/hi-risk-selection.md"};function p(c,E,m,u,D,C){const i=s("Mermaid");return t(),d("div",null,[E[2]||(E[2]=A('<h1 id="风险选择与-rothschild–stiglitz-的深化" tabindex="-1">风险选择与 Rothschild–Stiglitz 的深化 <a class="header-anchor" href="#风险选择与-rothschild–stiglitz-的深化" aria-label="Permalink to &quot;风险选择与 Rothschild–Stiglitz 的深化&quot;">​</a></h1><div class="epigraph"><p>保险公司卖的不是一份保单，是一个风险池；池子的构成比费率表更决定盈亏，于是每一条保单条款都同时是筛选工具。</p><footer>—— 据 Cutler and Zeckhauser, The Anatomy of Health Insurance, Handbook of Health Economics, 2000 整理</footer></div><p><a href="/econ/hi-demand-moralhazard">上一课</a>把合同给定之后的行为写清：保障压低自付价格，用量与预防两个边际同时动。缺口在签约之前——类型是私有的，高风险者更想要慷慨的保单。<a href="/econ/rs-unraveling">Rothschild–Stiglitz 崩溃</a>已经证明：竞争筛选下混同必被撇脂，分离在低风险足够多时也会被挖走。本课把那台机器开进健康保险的真实制度——计划菜单、雇主团购、风险调整与强制投保——看它在哪里照样运转、哪里被制度改写，不重写 1976 年的定理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>真实市场不提供「全保或部分保」两档，而提供一张慷慨度菜单：免赔高低、网络宽窄、专科药自付。三个真实装置使 RS 的压力比教科书更紧。其一，补贴固定：雇主的贡献额不随计划而变，慷慨计划的额外保费全由选择它的人承担——分离被政策做实了。其二，风险与道德风险同向：慷慨计划吸引的既是高风险者，也是上一课楔子下的高使用者，费率因此涨得比纯类型效应更快。其三，退出自由：健康者随时可以搬到便宜计划，死亡螺旋的每一环都不缺燃料。</p><h3 id="死亡螺旋" tabindex="-1">死亡螺旋 <a class="header-anchor" href="#死亡螺旋" aria-label="Permalink to &quot;死亡螺旋&quot;">​</a></h3><p>Cutler–Reber 的哈佛案例是标准教具：固定补贴下，慷慨计划费率上涨，健康者迁出，留下的池子更差，费率再涨，几年之内计划关停。这不是均衡不存在，而是存在的那条均衡路径通向收缩。</p><p><span class="marginnote">数字实例：设池中健康者年支出 1000 元、病者 10000 元、各占一半，平均保费 5500 元。健康者一盘算：自己的期望损失才 1000，花 5500 不划算，搬到便宜计划——留下的池子人均支出升到 10000，保费翻近一倍，下一批健康者跑得更快。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三个装置，各自对应 RS 的某种回应。风险调整：按年龄、性别、诊断的分数把保费在保险公司之间转移，把交叉补贴写成行政规则——Wilson 预期与 Miyazaki 想用合同内交叉补贴救存在性，制度用强制转账实现了它。强制投保加社区评级：不许定价于类型、不许不参保，低风险被留在池里，撇脂被禁止——用存在性换效率，是 RS 边界的原话。福利设计筛选：保险公司反过来用条款选择人群，窄网络劝退重症、专科药高自付劝退病者——这是供给侧的撇脂偏离，RS 的机器照转，只是方向反过来。</p>',10)),(t(),l(o,null,{default:B(()=>[r(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TYPE%5B%22%E5%81%A5%E5%BA%B7%E7%B1%BB%E5%9E%8B%E7%A7%81%E6%9C%89%22%5D%20--%3E%20MENU%5B%22%E6%85%B7%E6%85%A8%E5%BA%A6%E8%8F%9C%E5%8D%95%E8%87%AA%E9%80%89%22%5D%0A%20%20MENU%20--%3E%20SEL%5B%22%E9%A3%8E%E9%99%A9%E9%80%89%E6%8B%A9%EF%BC%9A%E7%97%85%E8%80%85%E9%80%89%E6%85%B7%E6%85%A8%22%5D%0A%20%20MHX%5B%22%E9%81%93%E5%BE%B7%E9%A3%8E%E9%99%A9%EF%BC%9A%E6%85%B7%E6%85%A8%E8%80%85%E7%94%A8%E5%BE%97%E5%A4%9A%22%5D%20--%3E%20SEL%0A%20%20SEL%20--%3E%20SPIRAL%5B%22%E8%B4%B9%E7%8E%87%E4%B8%8A%E6%B6%A8%E4%B8%8E%E8%BF%81%E5%87%BA%E7%9A%84%E6%AD%BB%E4%BA%A1%E8%9E%BA%E6%97%8B%22%5D%0A%20%20ADJ%5B%22%E9%A3%8E%E9%99%A9%E8%B0%83%E6%95%B4%EF%BC%9A%E6%8C%89%E5%8F%AF%E8%A7%82%E6%B5%8B%E5%88%86%E6%95%B0%E8%BD%AC%E8%B4%A6%22%5D%20--%3E%20SEL%0A%20%20MAND%5B%22%E5%BC%BA%E5%88%B6%E6%8A%95%E4%BF%9D%E4%B8%8E%E7%A4%BE%E5%8C%BA%E8%AF%84%E7%BA%A7%22%5D%20--%3E%20POOL%5B%22%E5%BC%BA%E5%88%B6%E6%B7%B7%E5%90%8C%EF%BC%9A%E5%AD%98%E5%9C%A8%E6%80%A7%E6%8D%A2%E6%95%88%E7%8E%87%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("把三个装置并排，共同点是：它们都只能对"),a("strong",null,"可观测维度"),e("操作。风险调整的分数解释不了支出的大头，剩下的不可观测部分照旧在选择；强制投保补的是参与边际，补不了强度边际；福利设计则专挑可观测维度打。所以每一代改革都把选择从上一维度推进下一维度：统一定价把选择推进参保与否，风险调整把选择推进诊断编码，福利设计把选择推进网络与药品层级。选择不会消失，只会换维度——这是本课最该带走的判断。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"术语翻译：风险调整=保险公司之间的转移支付。按年龄、性别、诊断给每名参保人打分，分数高的让保险公司从统筹基金里多领钱——让保险公司不再因为怕接到病人而撇脂。")],-1)),(t(),l(o,null,{default:B(()=>[r(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20S0%5B%22%E8%B5%B7%E7%82%B9%3A%20%E7%B1%BB%E5%9E%8B%E7%A7%81%E6%9C%89%2C%20%E8%87%AA%E7%94%B1%E9%80%89%E6%8B%A9%22%5D%20--%3E%20L1%5B%22%E7%BB%9F%E4%B8%80%E5%AE%9A%E4%BB%B7%3A%20%E9%80%89%E6%8B%A9%E9%80%80%E5%88%B0%E5%8F%82%E4%BF%9D%E4%B8%8E%E5%90%A6%22%5D%0A%20%20L1%20--%3E%20L2%5B%22%E9%A3%8E%E9%99%A9%E8%B0%83%E6%95%B4%3A%20%E9%80%89%E6%8B%A9%E9%80%80%E5%88%B0%E8%AF%8A%E6%96%AD%E7%BC%96%E7%A0%81%22%5D%0A%20%20L2%20--%3E%20L3%5B%22%E7%A6%8F%E5%88%A9%E8%AE%BE%E8%AE%A1%3A%20%E9%80%89%E6%8B%A9%E9%80%80%E5%88%B0%E7%BD%91%E7%BB%9C%E4%B8%8E%E8%8D%AF%E5%93%81%E5%B1%82%E7%BA%A7%22%5D%0A%20%20L3%20--%3E%20CONC%5B%22%E9%80%89%E6%8B%A9%E4%B8%8D%E4%BC%9A%E6%B6%88%E5%A4%B1%2C%20%E5%8F%AA%E4%BC%9A%E6%8D%A2%E7%BB%B4%E5%BA%A6%22%5D%0A%20%20FIX%5B%22%E5%BC%BA%E5%88%B6%E6%8A%95%E4%BF%9D%E4%B8%8E%E7%A4%BE%E5%8C%BA%E8%AF%84%E7%BA%A7%E6%8C%89%E4%BD%8F%E5%8F%82%E4%B8%8E%E8%BE%B9%E9%99%85%22%5D%20--%3E%20L1%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<p>测量上，<a href="/econ/akerlof-lemons">柠檬</a>的切断逻辑可以直接读数：覆盖弹性里混着选择与道德风险，区分它们靠只动其中一件工具的外生变化，与上一课识别道德风险的纪律相同。</p><p><span class="marginnote">风险调整模型的分数能解释的支出方差只是小头；解释不了的部分，正是保险公司最有激励去筛的人群。条款设计（窄网络、药品层级）因此常被读成「用福利设计做的定价」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写均衡不存在的参数区域，那是<a href="/econ/rs-unraveling">崩溃课</a>的内容；垄断筛选的菜单与信息租金是<a href="/econ/screening-rent">筛选课</a>的委托人版本，也不在此重算。动态选择（年轻时签终身合同）与多维类型（风险与健康行为同时私有）都没有展开。注意别把死亡螺旋读成必然：它是固定补贴与自由退出下的一条路径，风险调整与强制投保都在改它的参数。</p><p><span class="marginnote">常见误区：以为「统一定价、人人同价」就消灭了选择。同价只是把选择从价格维度赶进别的维度——诊断、网络、药品层级；看不见的选择不等于没有选择。</span></p><p>后课默认：类型私有加自由进入时，市场结构是制度设计的对象，不是给定的背景。下一课把镜头从保单转回人，看健康存量怎么进劳动供给。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>慷慨度菜单使选择与道德风险同向叠加，费率螺旋比纯类型模型更快。</li><li>风险调整、强制投保、社区评级是 RS 后继补丁的制度版本，都只作用于可观测维度。</li><li>选择不会消失，只会换维度：从价格退到诊断、网络与药品层级。</li><li>福利设计是供给侧撇脂：条款即定价。</li><li>出处：Rothschild–Stiglitz, <em>QJE</em> 1976；Cutler–Reber, <em>QJE</em> 1998；Cutler–Zeckhauser 2000；Einav–Finkelstein 对选择与道德风险测量的整理。</li></ul>',8))])}const _=n(h,[["render",p]]);export{S as __pageData,_ as default};
